head.script:
scwin.onpageload = function () {
    console.log("테넌트 관리 페이지 로드");

    // 페이지 로드 시 테넌트 데이터 조회
    scwin.loadTenantData();
};

// 테넌트 데이터 로드
scwin.loadTenantData = function () {
    // 검색 조건 초기화
    dmp_tenantVo.set("pageIndex", "1");
    dmp_tenantVo.set("pageSize", "50");

    // 서버 통신 - 테넌트 조회
    $c.sbm.execute($p, sbm_selectTenantVoList);
};

// 서버 응답 처리
scwin.sbm_tenantList_submitdone = function (e) {
    // error 수신시
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    console.log("테넌트 데이터 로드 완료:", elData);
    console.log("현재 필터 상태:", dmp_tenantVo.get("scStatus"));

    if (elData && elData.tenantVoList) {
        var filteredData = scwin.applyClientSideFilter(elData.tenantVoList);

        dlt_tenantVoList.setJSON(filteredData);

        console.warn("--- 데이터 모델 상태 확인 ---");
        console.log("DataList에 적용된 아이템 개수:", dlt_tenantVoList.getRowCount());
        console.log("DataList 실제 데이터:", dlt_tenantVoList.getAllJSON());

        var totalCount = filteredData.length;
        scwin.updateTenantCount(totalCount);

        scwin.updateTenantDisplay();
    }
};

scwin.applyClientSideFilter = function (dataList) {
    var filterStatus = dmp_tenantVo.get("scStatus");

    if (!filterStatus || filterStatus === "") {
        console.log("필터 없음 - 전체 데이터 반환:", dataList.length + "개");
        return dataList;
    }

    var filteredList = [];
    for (var i = 0; i < dataList.length; i++) {
        var item = dataList[i];
        var itemStatus = String(item.isActive).trim();

        if (filterStatus === "1" && (itemStatus === "1" || itemStatus === "Y")) {
            // 활성 필터
            filteredList.push(item);
        } else if (filterStatus === "0" && (itemStatus === "0" || itemStatus === "N")) {
            // 비활성 필터
            filteredList.push(item);
        }
    }

    console.log("필터링 결과:", filterStatus + " 상태로 필터링하여 " + filteredList.length + "개 / " + dataList.length + "개");
    return filteredList;
};

// 테넌트 개수 업데이트
scwin.updateTenantCount = function (count) {
    var countElement = $p.getComponentById("tenant_count");
    if (countElement) {
        countElement.setLabel("테넌트 목록 (" + count + "개)");
    }
};

scwin.updateTenantDisplay = function () {
    try {
        var loadingElement = $p.getComponentById("loading_state");
        if (loadingElement) {
            loadingElement.hide();
        }

        // DataList에서 데이터 가져오기
        var rowCount = dlt_tenantVoList.getRowCount();
        console.log("총 테넌트 개수:", rowCount);

        scwin.updateAndExtendTenantItems(rowCount);

        if (rowCount === 0) {
            scwin.showNoDataMessage();
        }

    } catch (e) {
        console.error("테넌트 목록 표시 중 오류:", e);
        scwin.showFallbackMessage();
    }
};

scwin.updateAndExtendTenantItems = function (totalCount) {
    try {
        console.log("필터링된 데이터로 UI 업데이트 시작:", totalCount + "개");

        scwin.createAllFilteredItems(totalCount);

    } catch (e) {
        console.error("테넌트 아이템 업데이트 중 오류:", e);
    }
};

scwin.createAllFilteredItems = function (totalCount) {
    try {
        var container = $p.getComponentById("tenant_list_container");
        if (!container) {
            console.error("컨테이너를 찾을 수 없습니다.");
            return;
        }

        container.removeAll();

        for (var i = 0; i < totalCount; i++) {
            var tenantData = dlt_tenantVoList.getRowJSON(i);
            scwin.createTenantItemByClone(container, tenantData, i);
        }
        console.log("필터링된 " + totalCount + "개 테넌트 아이템 생성 완료");

    } catch (e) {
        console.error("필터링된 아이템 생성 중 오류:", e);
    }
};
scwin.createFilteredTenantItem = function (container, tenantData, index) {
    try {
        // 컨테이너 DOM 요소 가져오기
        var containerElement = container.getElement ? container.getElement() : container;
        if (!containerElement) {
            console.error("컨테이너 DOM 요소를 찾을 수 없습니다.");
            return;
        }

        // 상태 값 변환
        var isActiveValue = String(tenantData.isActive).trim();
        var statusText, statusClass;

        if (isActiveValue === "1" || isActiveValue === "Y" || isActiveValue === "true") {
            statusText = "활성";
            statusClass = "status-active";
        } else if (isActiveValue === "0" || isActiveValue === "N" || isActiveValue === "false") {
            statusText = "비활성";
            statusClass = "status-inactive";
        } else {
            statusText = "알 수 없음";
            statusClass = "status-inactive";
        }

        // 날짜 포맷팅
        var createdDate = tenantData.createdAt ? tenantData.createdAt.split(' ')[0] : "";

        // 실제 DB 데이터가 있으면 사용, 없으면 "정보 없음" 표시
        var userCount = tenantData.userCount || "정보 없음";
        var moduleCount = tenantData.moduleCount || "정보 없음";

        // 새로운 div 요소 생성
        var newItemDiv = document.createElement('div');
        newItemDiv.className = 'tenant-item filtered-item';
        newItemDiv.id = 'filtered_tenant_' + index;

        // 디버깅을 위한 데이터 속성 추가
        newItemDiv.setAttribute('data-tenant-id', tenantData.tenantId);
        newItemDiv.setAttribute('data-is-active', tenantData.isActive);
        newItemDiv.setAttribute('data-status', statusText);

        // 내용 HTML 설정
        newItemDiv.innerHTML = `
            <div class="tenant-name">${tenantData.name || 'Unknown'}</div>
            <div class="tenant-info">사용자: ${userCount}${typeof userCount === 'number' ? '명' : ''}</div>
            <div class="tenant-info">모듈: ${moduleCount}${typeof moduleCount === 'number' ? '개' : ''} | 생성일: ${createdDate}</div>
            <div class="tenant-status ${statusClass}">${statusText}</div>
        `;

        // 컨테이너에 추가
        containerElement.appendChild(newItemDiv);

        console.log("✅ 필터링된 테넌트 아이템 생성:", {
            index: index + 1,
            name: tenantData.name,
            status: statusText,
            id: newItemDiv.id,
            isActive: tenantData.isActive
        });

    } catch (e) {
        console.error("필터링된 테넌트 아이템 생성 중 오류:", e, index, tenantData);
    }
};

scwin.createClonedTenantItem = function (templateItem, container, tenantData, index) {
    try {
        var containerElement = container.getElement ? container.getElement() : container;
        if (!containerElement) {
            console.error("컨테이너 DOM 요소를 찾을 수 없습니다.");
            return;
        }

        console.log("동적 테넌트 " + (index + 1) + " 상태 데이터:", tenantData.isActive, typeof tenantData.isActive);

        var isActiveValue = String(tenantData.isActive).trim();
        var statusText, statusClass;

        if (isActiveValue === "1" || isActiveValue === "Y" || isActiveValue === "true") {
            statusText = "활성";
            statusClass = "status-active";
        } else if (isActiveValue === "0" || isActiveValue === "N" || isActiveValue === "false") {
            statusText = "비활성";
            statusClass = "status-inactive";
        } else {
            statusText = "알 수 없음";
            statusClass = "status-inactive";
        }

        console.log("동적 아이템 변환된 상태:", statusText, statusClass);

        // 날짜 포맷팅
        var createdDate = tenantData.createdAt ? tenantData.createdAt.split(' ')[0] : "";

        // 실제 DB 데이터가 있으면 사용, 없으면 "정보 없음" 표시
        var userCount = tenantData.userCount || "정보 없음";
        var moduleCount = tenantData.moduleCount || "정보 없음";

        // 새로운 div 요소 생성
        var newItemDiv = document.createElement('div');
        newItemDiv.className = 'tenant-item';
        newItemDiv.id = 'dynamic_tenant_' + index;

        // 내용 HTML 설정
        newItemDiv.innerHTML = `
            <div class="tenant-name">${tenantData.name || 'Unknown'}</div>
            <div class="tenant-info">사용자: ${userCount}${typeof userCount === 'number' ? '명' : ''}</div>
            <div class="tenant-info">모듈: ${moduleCount}${typeof moduleCount === 'number' ? '개' : ''} | 생성일: ${createdDate}</div>
            <div class="tenant-status ${statusClass}">${statusText}</div>
        `;

        // 컨테이너에 추가
        containerElement.appendChild(newItemDiv);

        console.log("동적 테넌트 아이템 생성:", index + 1, tenantData.name, statusText);

    } catch (e) {
        console.error("복제 테넌트 아이템 생성 중 오류:", e, index, tenantData);
    }
};

// 개별 테넌트 아이템 업데이트
scwin.updateTenantItem = function (itemIndex, tenantData) {
    try {
        var staticItem = $p.getComponentById("static_tenant_" + itemIndex);
        if (!staticItem || !tenantData) {
            return;
        }

        console.log("테넌트 " + itemIndex + " 상태 데이터:", tenantData.isActive, typeof tenantData.isActive);

        var isActiveValue = String(tenantData.isActive).trim();
        var statusText, statusClass;

        if (isActiveValue === "1" || isActiveValue === "Y" || isActiveValue === "true") {
            statusText = "활성";
            statusClass = "status-active";
        } else if (isActiveValue === "0" || isActiveValue === "N" || isActiveValue === "false") {
            statusText = "비활성";
            statusClass = "status-inactive";
        } else {
            statusText = "알 수 없음";
            statusClass = "status-inactive";
        }

        console.log("변환된 상태:", statusText, statusClass);

        // 날짜 포맷팅
        var createdDate = tenantData.createdAt ? tenantData.createdAt.split(' ')[0] : "";

        // 실제 DB 데이터가 있으면 사용, 없으면 "정보 없음" 표시
        var userCount = tenantData.userCount || "정보 없음";
        var moduleCount = tenantData.moduleCount || "정보 없음";

        // 각 텍스트박스 요소 찾아서 업데이트
        var children = staticItem.getChildren();
        if (children && children.length >= 4) {
            // 첫 번째: 테넌트명
            children[0].setLabel(tenantData.name || 'Unknown');

            // 두 번째: 사용자 정보
            children[1].setLabel("사용자: " + userCount + (typeof userCount === 'number' ? '명' : ''));

            // 세 번째: 모듈 및 생성일 정보
            children[2].setLabel("모듈: " + moduleCount + (typeof moduleCount === 'number' ? '개' : '') + " | 생성일: " + createdDate);

            // 네 번째: 상태 (setClass 대신 다른 방법 사용)
            children[3].setLabel(statusText);

            // CSS 클래스 변경을 위한 대안 방법
            try {
                if (children[3].addClass && children[3].removeClass) {
                    // 기존 클래스 제거
                    children[3].removeClass("status-active");
                    children[3].removeClass("status-inactive");
                    // 새 클래스 추가
                    children[3].addClass(statusClass);
                } else if (children[3].getElement) {
                    // DOM 요소 직접 접근
                    var element = children[3].getElement();
                    if (element) {
                        element.className = "tenant-status " + statusClass;
                    }
                }
            } catch (classError) {
                console.log("CSS 클래스 변경 실패, 텍스트만 업데이트:", classError);
            }
        }

        // 아이템 표시
        staticItem.show();

        console.log("테넌트 아이템 업데이트 완료:", itemIndex, tenantData.name, statusText);

    } catch (e) {
        console.error("테넌트 아이템 업데이트 중 오류:", e, itemIndex, tenantData);
    }
};

// 데이터 없음 메시지 표시
scwin.showNoDataMessage = function () {
    try {
        // 모든 정적 아이템 숨기기
        for (var i = 1; i <= 4; i++) {
            var staticItem = $p.getComponentById("static_tenant_" + i);
            if (staticItem) {
                staticItem.hide();
            }
        }

        // 첫 번째 아이템을 "데이터 없음" 메시지로 사용
        var firstItem = $p.getComponentById("static_tenant_1");
        if (firstItem) {
            var children = firstItem.getChildren();
            if (children && children.length >= 1) {
                children[0].setLabel("조회된 테넌트가 없습니다.");
                children[0].setClass("tenant-name" + " no-data-message");
            }

            // 나머지 텍스트 요소들 숨기기
            for (var j = 1; j < children.length; j++) {
                children[j].setLabel("");
                children[j].hide();
            }

            firstItem.show();
        }
    } catch (e) {
        console.error("데이터 없음 메시지 표시 중 오류:", e);
    }
};

// 검색 기능
scwin.searchTenant = function () {
    var searchValue = $p.getComponentById("searchInput").getValue();

    if (searchValue && searchValue.trim() !== "") {
        // 검색어가 있는 경우
        dmp_tenantVo.set("scName", searchValue.trim());
        dmp_tenantVo.set("scTenantId", searchValue.trim());
    } else {
        // 검색어가 없는 경우 초기화
        dmp_tenantVo.set("scName", "");
        dmp_tenantVo.set("scTenantId", "");
    }

    // 페이지 번호 초기화
    dmp_tenantVo.set("pageIndex", "1");

    // 검색 실행
    $c.sbm.execute($p, sbm_selectTenantVoList);

    console.log("검색어:", searchValue);
};

// 필터 기능들
scwin.filterAll = function () {
    console.log("전체 필터");
    dmp_tenantVo.set("scStatus", "");
    scwin.updateFilterButtons("all");
    scwin.loadTenantData();
};

scwin.filterActive = function () {
    console.log("활성 필터");
    // 서버 필터링용 (isActive = 1 또는 Y)
    dmp_tenantVo.set("scStatus", "1");
    scwin.updateFilterButtons("active");
    scwin.loadTenantData();
};

scwin.filterInactive = function () {
    console.log("비활성 필터");
    // 서버 필터링용 (isActive = 0 또는 N)
    dmp_tenantVo.set("scStatus", "0");
    scwin.updateFilterButtons("inactive");
    scwin.loadTenantData();
};

// 필터 버튼 상태 업데이트
scwin.updateFilterButtons = function (activeFilter) {
    // 모든 필터 버튼의 클래스 초기화
    var allBtn = $p.getComponentById("filter_all");
    var activeBtn = $p.getComponentById("filter_active");
    var inactiveBtn = $p.getComponentById("filter_inactive");

    // 클래스 초기화 (실제 구현시 적절한 메서드 사용)
    if (allBtn) allBtn.removeClass("active");
    if (activeBtn) activeBtn.removeClass("active");
    if (inactiveBtn) inactiveBtn.removeClass("active");

    // 선택된 버튼에 active 클래스 추가
    switch (activeFilter) {
        case "all":
            if (allBtn) allBtn.addClass("active");
            break;
        case "active":
            if (activeBtn) activeBtn.addClass("active");
            break;
        case "inactive":
            if (inactiveBtn) inactiveBtn.addClass("active");
            break;
    }
};

// 네비게이션 이벤트들
scwin.btn_home_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_dashboard.xml";
};

scwin.btn_tenant_onclick = function () {
    console.log("현재 테넌트 페이지");
};

scwin.btn_module_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_module.xml";
};

scwin.btn_stats_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_server_info.xml";
};

// 새로고침 기능
scwin.refreshData = function () {
    scwin.loadTenantData();
};

scwin.createTenantItemByClone = function (container, tenantData, index) {
    try {
        var newTenantComp = WebSquare.util.cloneComponent("tenant_template");

        newTenantComp.setId("dynamic_tenant_" + index);

        var nameBox = newTenantComp.getChild("template_name", true);
        var usersBox = newTenantComp.getChild("template_users", true);
        var modulesBox = newTenantComp.getChild("template_modules", true);
        var statusBox = newTenantComp.getChild("template_status", true);

        var isActiveValue = String(tenantData.isActive).trim();
        var statusText, statusClass;
        if (isActiveValue === "1" || isActiveValue === "Y" || isActiveValue === "true") {
            statusText = "활성";
            statusClass = "status-active";
        } else {
            statusText = "비활성";
            statusClass = "status-inactive";
        }

        var createdDate = tenantData.createdAt ? tenantData.createdAt.split(' ')[0] : "";
        var userCount = tenantData.userCount || "정보 없음";
        var moduleCount = tenantData.moduleCount || "정보 없음";

        nameBox.setLabel(tenantData.name || 'Unknown');
        usersBox.setLabel("사용자: " + userCount + (typeof userCount === 'number' ? '명' : ''));
        modulesBox.setLabel("모듈: " + moduleCount + (typeof moduleCount === 'number' ? '개' : '') + " | 생성일: " + createdDate);
        statusBox.setLabel(statusText);

        statusBox.removeClass("status-active status-inactive"); // 기존 클래스 제거
        statusBox.addClass(statusClass); // 새 클래스 추가

        container.insertChild(newTenantComp);

        console.log(`✅ [프레임워크 방식] ${index + 1}번째 아이템 생성: ${tenantData.name}`);

    } catch (e) {
        console.error("컴포넌트 복제 및 생성 중 오류 발생", index, e);
    }
};
